---@alias gcp.storagetransfer_v1.MetadataOptionsGidEnum "GID_UNSPECIFIED"|"GID_SKIP"|"GID_NUMBER"

---@alias gcp.storagetransfer_v1.MetadataOptionsKmsKeyEnum "KMS_KEY_UNSPECIFIED"|"KMS_KEY_DESTINATION_BUCKET_DEFAULT"|"KMS_KEY_PRESERVE"

---@alias gcp.storagetransfer_v1.MetadataOptionsModeEnum "MODE_UNSPECIFIED"|"MODE_SKIP"|"MODE_PRESERVE"

---@alias gcp.storagetransfer_v1.MetadataOptionsStorageClassEnum "STORAGE_CLASS_UNSPECIFIED"|"STORAGE_CLASS_DESTINATION_BUCKET_DEFAULT"|"STORAGE_CLASS_PRESERVE"|"STORAGE_CLASS_STANDARD"|"STORAGE_CLASS_NEARLINE"|"STORAGE_CLASS_COLDLINE"|"STORAGE_CLASS_ARCHIVE"

---@alias gcp.storagetransfer_v1.MetadataOptionsSymlinkEnum "SYMLINK_UNSPECIFIED"|"SYMLINK_SKIP"|"SYMLINK_PRESERVE"

